'use client';

import { useGoogleLogin } from '@react-oauth/google';
import { useRouter } from 'next/navigation';
import axios from 'axios';
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { useAuth } from '@/contexts/auth-context';

interface GoogleLoginButtonProps {
  className?: string;
  children?: React.ReactNode;
}

export default function GoogleLoginButton({ 
  className,
  children 
}: GoogleLoginButtonProps) {
  const router = useRouter();
  const { setUser, setIsAuthenticated } = useAuth();
  const [isLoading, setIsLoading] = useState(false);

  const login = useGoogleLogin({
    onSuccess: async (tokenResponse) => {
      setIsLoading(true);
      
      try {
        // 1. Récupérer les informations du profil Google
        const userInfoResponse = await axios.get(
          'https://www.googleapis.com/oauth2/v3/userinfo',
          {
            headers: {
              Authorization: `Bearer ${tokenResponse.access_token}`,
            },
          }
        );

        const googleData = userInfoResponse.data;

        // 2. Envoyer les données à votre backend Django
        const response = await axios.post(
          `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000'}/api/users/google_auth/`,
          {
            access_token: tokenResponse.access_token,
            uid: googleData.sub,
            email: googleData.email,
            given_name: googleData.given_name,
            family_name: googleData.family_name,
            profile_data: googleData,
          },
          {
            headers: {
              'Content-Type': 'application/json',
            },
          }
        );

        // 3. Stocker les tokens dans localStorage
        localStorage.setItem('access_token', response.data.tokens.access);
        localStorage.setItem('refresh_token', response.data.tokens.refresh);
        localStorage.setItem('user', JSON.stringify(response.data.user));

        // 4. Mettre à jour le contexte d'authentification
        setUser(response.data.user);
        setIsAuthenticated(true);

        console.log('✅ Authentification Google réussie:', {
          user: response.data.user,
          is_new_user: response.data.is_new_user,
          redirect: response.data.redirect_url
        });

        // 5. Rediriger selon si c'est un nouvel utilisateur
        if (response.data.is_new_user) {
          router.push('/preferences/');
        } else {
          router.push('/#hero');
        }

      } catch (error: any) {
        console.error('❌ Erreur lors de l\'authentification Google:', error);
        
        if (error.response) {
          console.error('Erreur serveur:', error.response.data);
          alert(`Erreur: ${error.response.data.error || 'Erreur serveur'}`);
        } else if (error.request) {
          console.error('Pas de réponse du serveur');
          alert('Impossible de contacter le serveur. Vérifiez votre connexion.');
        } else {
          console.error('Erreur:', error.message);
          alert('Une erreur est survenue lors de la connexion');
        }
      } finally {
        setIsLoading(false);
      }
    },
    onError: (error) => {
      console.error('❌ Erreur Google OAuth:', error);
      alert('Erreur lors de la connexion avec Google');
      setIsLoading(false);
    },
  });

  return (
    <Button
      type="button"
      variant="outline"
      onClick={() => login()}
      disabled={isLoading}
      className={className}
    >
      {isLoading ? (
        <>
          <div className="w-5 h-5 mr-2 border-2 border-gray-300 border-t-blue-600 rounded-full animate-spin"></div>
          Connexion en cours...
        </>
      ) : (
        <>
          <svg className="w-5 h-5 mr-2" viewBox="0 0 24 24">
            <path
              fill="#4285F4"
              d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
            />
            <path
              fill="#34A853"
              d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
            />
            <path
              fill="#FBBC05"
              d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
            />
            <path
              fill="#EA4335"
              d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
            />
          </svg>
          {children}
        </>
      )}
    </Button>
  );
}